INSERT INTO traductions (langue, cle, texte, source_fr) VALUES
($t$de$t$, $t$ch-votes-def$t$, $t$eine Zeile pro Ratsmitglied und Abstimmung, bei der es sich geäussert hat: <code>position</code> = pour (Ja), contre (Nein), abstention (Enthaltung) oder non_votant (der Präsident stimmt nicht). Abwesende («hat nicht teilgenommen», «entschuldigt») sind nicht enthalten.$t$, $t$une ligne par conseiller et par vote où il s'est exprimé : <code>position</code> = pour (oui), contre (non), abstention, ou non_votant (le président ne vote pas). Les absents (« n'a pas pris part », « excusé ») ne sont pas inclus.$t$),
($t$it$t$, $t$ch-votes-def$t$, $t$una riga per consigliere e per votazione in cui si è espresso: <code>position</code> = pour (sì), contre (no), abstention (astensione) o non_votant (il presidente non vota). Gli assenti («non ha partecipato», «scusato») non sono inclusi.$t$, $t$une ligne par conseiller et par vote où il s'est exprimé : <code>position</code> = pour (oui), contre (non), abstention, ou non_votant (le président ne vote pas). Les absents (« n'a pas pris part », « excusé ») ne sont pas inclus.$t$),
($t$de$t$, $t$ch-absents-def$t$, $t$<strong>Abwesende stehen nicht in <code>ch_votes</code></strong>: Sie ergeben sich. Ein Ratsmitglied ist bei einer Abstimmung abwesend, wenn es am Datum ein laufendes Mandat hatte (Datei <code>ch_mandats</code>, Daten der Quelle) und keine Zeile in <code>ch_votes</code> hat.$t$, $t$<strong>Les absents ne sont pas dans <code>ch_votes</code></strong> : ils se déduisent. Un conseiller est absent à un vote s'il avait un mandat en cours à sa date (fichier <code>ch_mandats</code>, dates de la source) et aucune ligne dans <code>ch_votes</code>.$t$),
($t$it$t$, $t$ch-absents-def$t$, $t$<strong>Gli assenti non sono in <code>ch_votes</code></strong>: si deducono. Un consigliere è assente a una votazione se alla data aveva un mandato in corso (file <code>ch_mandats</code>, date della fonte) e nessuna riga in <code>ch_votes</code>.$t$, $t$<strong>Les absents ne sont pas dans <code>ch_votes</code></strong> : ils se déduisent. Un conseiller est absent à un vote s'il avait un mandat en cours à sa date (fichier <code>ch_mandats</code>, dates de la source) et aucune ligne dans <code>ch_votes</code>.$t$),
($t$de$t$, $t$ch-scrutins-def$t$, $t$<code>nb_pour</code>, <code>nb_contre</code>, <code>nb_abstentions</code>: im Nationalrat von der Website anhand der Stimmzettel <strong>berechnet</strong> (die Quelle veröffentlicht dort keine Gesamtergebnisse); im Ständerat offizielle Zählung der Quelle. <code>sort</code>: berechnet (mehr Ja als Nein). <code>sur_ensemble</code>: «Schlussabstimmung» oder «Gesamtabstimmung» (berechnet anhand des Abstimmungsgegenstands). <code>url_officielle</code>: offizielle Seite des Geschäfts (Curia Vista).$t$, $t$<code>nb_pour</code>, <code>nb_contre</code>, <code>nb_abstentions</code> : <strong>calculés</strong> par le site d'après les bulletins au Conseil national (la source n'y publie pas de totaux) ; décompte officiel de la source au Conseil des États. <code>sort</code> : calculé (plus de oui que de non). <code>sur_ensemble</code> : « vote final » ou « vote sur l'ensemble » (calculé d'après l'objet du vote). <code>url_officielle</code> : fiche officielle de l'affaire (Curia Vista).$t$),
($t$it$t$, $t$ch-scrutins-def$t$, $t$<code>nb_pour</code>, <code>nb_contre</code>, <code>nb_abstentions</code>: al Consiglio nazionale <strong>calcolati</strong> dal sito in base alle schede (la fonte non vi pubblica totali); al Consiglio degli Stati conteggio ufficiale della fonte. <code>sort</code>: calcolato (più sì che no). <code>sur_ensemble</code>: «votazione finale» o «votazione sul complesso» (calcolato in base all'oggetto del voto). <code>url_officielle</code>: scheda ufficiale dell'oggetto (Curia Vista).$t$, $t$<code>nb_pour</code>, <code>nb_contre</code>, <code>nb_abstentions</code> : <strong>calculés</strong> par le site d'après les bulletins au Conseil national (la source n'y publie pas de totaux) ; décompte officiel de la source au Conseil des États. <code>sort</code> : calculé (plus de oui que de non). <code>sur_ensemble</code> : « vote final » ou « vote sur l'ensemble » (calculé d'après l'objet du vote). <code>url_officielle</code> : fiche officielle de l'affaire (Curia Vista).$t$),
($t$de$t$, $t$donnees-sources-suisse$t$, $t$Die Abstimmungen stammen aus den offenen Daten der <strong>Parlamentsdienste</strong> («Parlamentsdienste der Bundesversammlung, Bern») und werden unverändert übernommen; von der Website berechnete Gesamtergebnisse, Ergebnisse und Fraktionen sind als solche gekennzeichnet. Das Datum der letzten Aktualisierung steht bei jeder Datei. Siehe die Seite <a href="{0}">Methodik und Grenzen</a>. Es sind keine Fotos enthalten.$t$, $t$Les votes viennent des données ouvertes des <strong>Services du Parlement</strong> (« Parlamentsdienste der Bundesversammlung, Bern »), reprises sans modification ; les totaux, résultats et groupes calculés par le site sont signalés comme tels. La date de dernière mise à jour est affichée avec chaque fichier. Voir la page <a href="{0}">Méthodologie et limites</a>. Aucune photo n'est incluse.$t$),
($t$it$t$, $t$donnees-sources-suisse$t$, $t$Le votazioni provengono dai dati aperti dei <strong>Servizi del Parlamento</strong> («Parlamentsdienste der Bundesversammlung, Bern»), ripresi senza modifiche; i totali, i risultati e i gruppi calcolati dal sito sono segnalati come tali. La data dell'ultimo aggiornamento è indicata con ogni file. Vedere la pagina <a href="{0}">Metodologia e limiti</a>. Non sono incluse foto.$t$, $t$Les votes viennent des données ouvertes des <strong>Services du Parlement</strong> (« Parlamentsdienste der Bundesversammlung, Bern »), reprises sans modification ; les totaux, résultats et groupes calculés par le site sont signalés comme tels. La date de dernière mise à jour est affichée avec chaque fichier. Voir la page <a href="{0}">Méthodologie et limites</a>. Aucune photo n'est incluse.$t$),
($t$de$t$, $t$ces-fichiers-ne-contiennent-que-les-4$t$, $t$Diese Dateien enthalten nur die Daten der Schweiz (Nationalrat und Ständerat): Ihr Name beginnt mit <code>ch_</code>. Die Abstimmungen stehen in <code>ch_scrutins</code>, die Stimmzettel in <code>ch_votes</code>; abwesende Ratsmitglieder werden nicht gespeichert (sie ergeben sich aus den Mandaten).$t$, $t$Ces fichiers ne contiennent que les données de la Suisse (Conseil national et Conseil des États) : leur nom commence par <code>ch_</code>. Les votes sont dans <code>ch_scrutins</code>, les bulletins dans <code>ch_votes</code> ; les conseillers absents ne sont pas stockés (ils se déduisent des mandats).$t$),
($t$it$t$, $t$ces-fichiers-ne-contiennent-que-les-4$t$, $t$Questi file contengono solo i dati della Svizzera (Consiglio nazionale e Consiglio degli Stati): il loro nome inizia con <code>ch_</code>. Le votazioni sono in <code>ch_scrutins</code>, le schede in <code>ch_votes</code>; i consiglieri assenti non sono memorizzati (si deducono dai mandati).$t$, $t$Ces fichiers ne contiennent que les données de la Suisse (Conseil national et Conseil des États) : leur nom commence par <code>ch_</code>. Les votes sont dans <code>ch_scrutins</code>, les bulletins dans <code>ch_votes</code> ; les conseillers absents ne sont pas stockés (ils se déduisent des mandats).$t$),
($t$de$t$, $t$participation-aux-votes-du-parlement-suisse$t$, $t$Stimmbeteiligung der Bundesversammlung$t$, $t$Participation aux votes de l'Assemblée fédérale$t$),
($t$it$t$, $t$participation-aux-votes-du-parlement-suisse$t$, $t$Partecipazione alle votazioni dell'Assemblea federale$t$, $t$Participation aux votes de l'Assemblée fédérale$t$),
($t$de$t$, $t$accueil-apropos-titre$t$, $t$So liest man die Abstimmungen des Parlaments$t$, $t$Comment lire les votes du Parlement$t$),
($t$it$t$, $t$accueil-apropos-titre$t$, $t$Come leggere le votazioni del Parlamento$t$, $t$Comment lire les votes du Parlement$t$),
($t$de$t$, $t$accueil-apropos-texte$t$, $t$Diese Website vereint die namentlichen Abstimmungen der Parlamente aus ihren offiziellen offenen Daten: bei jeder namentlichen Abstimmung, wie jedes Mitglied abgestimmt hat (Ja, Nein, Enthaltung, nicht teilgenommen), die Ergebnisse nach Fraktion und bei Gesetzen der ganze Weg des Textes. Die Website urteilt über niemanden: Ein Abwesender ist ein Abwesender, und jede berechnete, zweifelhafte oder fehlende Angabe wird als solche gekennzeichnet.$t$, $t$Ce site rassemble les votes nominatifs des assemblées parlementaires à partir de leurs données ouvertes officielles : pour chaque scrutin public, le vote de chaque député ou sénateur (pour, contre, abstention, n'a pas pris part au vote), les résultats par groupe politique, et, pour les lois, le parcours complet du texte : vote dans chaque chambre, décision du Conseil constitutionnel, promulgation et parution au Journal officiel. Le site ne juge personne : un absent est un absent, et toute donnée calculée, douteuse ou manquante est signalée comme telle.$t$),
($t$it$t$, $t$accueil-apropos-texte$t$, $t$Questo sito riunisce le votazioni nominali dei parlamenti a partire dai loro dati aperti ufficiali: per ogni votazione nominale, come ha votato ciascun membro (sì, no, astensione, non ha partecipato), i risultati per gruppo e, per le leggi, l'intero percorso del testo. Il sito non giudica nessuno: un assente è un assente, e ogni dato calcolato, dubbio o mancante è segnalato come tale.$t$, $t$Ce site rassemble les votes nominatifs des assemblées parlementaires à partir de leurs données ouvertes officielles : pour chaque scrutin public, le vote de chaque député ou sénateur (pour, contre, abstention, n'a pas pris part au vote), les résultats par groupe politique, et, pour les lois, le parcours complet du texte : vote dans chaque chambre, décision du Conseil constitutionnel, promulgation et parution au Journal officiel. Le site ne juge personne : un absent est un absent, et toute donnée calculée, douteuse ou manquante est signalée comme telle.$t$),
($t$de$t$, $t$scrutin-phrase-neutre$t$, $t$Am {0}, {1}: {2:N0} Ja, {3:N0} Nein, {4:N0} Enthaltungen.$t$, $t$Le {0}, {1} : {2:N0} pour, {3:N0} contre, {4:N0} abstentions.$t$),
($t$it$t$, $t$scrutin-phrase-neutre$t$, $t$Il {0}, {1}: {2:N0} a favore, {3:N0} contro, {4:N0} astenuti.$t$, $t$Le {0}, {1} : {2:N0} pour, {3:N0} contre, {4:N0} abstentions.$t$),
($t$de$t$, $t$scrutin-phrase-adopte$t$, $t$Am {0}, {1}: Abstimmung angenommen, {2:N0} Ja, {3:N0} Nein, {4:N0} Enthaltungen.$t$, $t$Le {0}, {1} : vote adopté, {2:N0} pour, {3:N0} contre, {4:N0} abstentions.$t$),
($t$it$t$, $t$scrutin-phrase-adopte$t$, $t$Il {0}, {1}: votazione approvata, {2:N0} a favore, {3:N0} contro, {4:N0} astenuti.$t$, $t$Le {0}, {1} : vote adopté, {2:N0} pour, {3:N0} contre, {4:N0} abstentions.$t$),
($t$de$t$, $t$scrutin-phrase-rejete$t$, $t$Am {0}, {1}: Abstimmung abgelehnt, {2:N0} Ja, {3:N0} Nein, {4:N0} Enthaltungen.$t$, $t$Le {0}, {1} : vote rejeté, {2:N0} pour, {3:N0} contre, {4:N0} abstentions.$t$),
($t$it$t$, $t$scrutin-phrase-rejete$t$, $t$Il {0}, {1}: votazione respinta, {2:N0} a favore, {3:N0} contro, {4:N0} astenuti.$t$, $t$Le {0}, {1} : vote rejeté, {2:N0} pour, {3:N0} contre, {4:N0} abstentions.$t$),
($t$de$t$, $t$methodo-ch-source$t$, $t$<strong>Nationalrat und Ständerat</strong>: <strong>offizielle</strong> Quelle, der Open-Data-Dienst der Parlamentsdienste (<a href="https://www.parlament.ch/fr/services/open-data-webservices">parlament.ch</a>) und, für den Ständerat, dessen Schnittstelle mit Schlüssel: ein Stimmzettel pro Ratsmitglied und Abstimmung, Verzeichnis der Ratsmitglieder mit ihren <strong>datierten Mandaten</strong>. Genannte Quelle: «Parlamentsdienste der Bundesversammlung, Bern». Die Daten werden unverändert übernommen (die herunterladbaren Dateien sind die Daten der Quelle); das Datum der letzten Aktualisierung wird angezeigt.$t$, $t$<strong>Conseil national et Conseil des États</strong> : source <strong>officielle</strong>, le service de données ouvertes des Services du Parlement (<a href="https://www.parlament.ch/fr/services/open-data-webservices">parlament.ch</a>) et, pour le Conseil des États, son interface à clé : un bulletin par conseiller et par vote, annuaire des conseillers avec leurs <strong>mandats datés</strong>. Source citée : « Parlamentsdienste der Bundesversammlung, Bern ». Les données sont reprises sans modification (les fichiers téléchargeables sont les données de la source) ; la date de la dernière mise à jour est affichée.$t$),
($t$it$t$, $t$methodo-ch-source$t$, $t$<strong>Consiglio nazionale e Consiglio degli Stati</strong>: fonte <strong>ufficiale</strong>, il servizio di dati aperti dei Servizi del Parlamento (<a href="https://www.parlament.ch/fr/services/open-data-webservices">parlament.ch</a>) e, per il Consiglio degli Stati, la sua interfaccia con chiave: una scheda per consigliere e per votazione, elenco dei consiglieri con i loro <strong>mandati datati</strong>. Fonte citata: «Parlamentsdienste der Bundesversammlung, Bern». I dati sono ripresi senza modifiche (i file scaricabili sono i dati della fonte); la data dell'ultimo aggiornamento è indicata.$t$, $t$<strong>Conseil national et Conseil des États</strong> : source <strong>officielle</strong>, le service de données ouvertes des Services du Parlement (<a href="https://www.parlament.ch/fr/services/open-data-webservices">parlament.ch</a>) et, pour le Conseil des États, son interface à clé : un bulletin par conseiller et par vote, annuaire des conseillers avec leurs <strong>mandats datés</strong>. Source citée : « Parlamentsdienste der Bundesversammlung, Bern ». Les données sont reprises sans modification (les fichiers téléchargeables sont les données de la source) ; la date de la dernière mise à jour est affichée.$t$),
($t$de$t$, $t$methodo-ch-positions$t$, $t$<strong>Ja, Nein, Enthaltung</strong>: wie veröffentlicht. <strong>Der Präsident stimmt nicht</strong>: als erklärter Nichtabstimmender gezählt.$t$, $t$<strong>Oui, non, abstention</strong> : tels que publiés. <strong>Le président ne vote pas</strong> : compté comme non-votant déclaré.$t$),
($t$it$t$, $t$methodo-ch-positions$t$, $t$<strong>Sì, no, astensione</strong>: come pubblicati. <strong>Il presidente non vota</strong>: conteggiato come non votante dichiarato.$t$, $t$<strong>Oui, non, abstention</strong> : tels que publiés. <strong>Le président ne vote pas</strong> : compté comme non-votant déclaré.$t$),
($t$de$t$, $t$methodo-ch-absent$t$, $t$<strong>Abwesend</strong>: Das Ratsmitglied hatte am Abstimmungstag ein Mandat, hat aber nicht abgestimmt («hat nicht an der Abstimmung teilgenommen» oder «entschuldigt» in der Quelle). Die Website nennt <em>keinen Grund</em>.$t$, $t$<strong>Absent</strong> : le conseiller siégeait à la date du vote mais n'a pas voté (« n'a pas pris part au vote » ou « excusé » dans la source). Le site ne donne <em>aucune raison</em>.$t$),
($t$it$t$, $t$methodo-ch-absent$t$, $t$<strong>Assente</strong>: il consigliere sedeva alla data del voto ma non ha votato («non ha partecipato al voto» o «scusato» nella fonte). Il sito non indica <em>alcun motivo</em>.$t$, $t$<strong>Absent</strong> : le conseiller siégeait à la date du vote mais n'a pas voté (« n'a pas pris part au vote » ou « excusé » dans la source). Le site ne donne <em>aucune raison</em>.$t$),
($t$de$t$, $t$methodo-ch-calcule$t$, $t$<strong>Gesamtergebnisse und Ergebnis</strong>: im Nationalrat von der Website anhand der Stimmzettel <strong>berechnet</strong> (die Quelle veröffentlicht weder Gesamtergebnisse noch ein Ergebnis); im Ständerat <strong>offizielle</strong> Zählung der Quelle. In beiden Fällen: «angenommen» = mehr Ja als Nein (<strong>berechnet</strong>), bei Gleichstand wird nichts angezeigt.$t$, $t$<strong>Totaux et résultat</strong> : au Conseil national, <strong>calculés</strong> par le site d'après les bulletins (la source ne publie ni totaux ni résultat) ; au Conseil des États, décompte <strong>officiel</strong> de la source. Dans les deux cas, « adopté » = plus de oui que de non (<strong>calculé</strong>), rien d'indiqué en cas d'égalité.$t$),
($t$it$t$, $t$methodo-ch-calcule$t$, $t$<strong>Totali e risultato</strong>: al Consiglio nazionale <strong>calcolati</strong> dal sito in base alle schede (la fonte non pubblica né totali né risultato); al Consiglio degli Stati conteggio <strong>ufficiale</strong> della fonte. In entrambi i casi «approvato» = più sì che no (<strong>calcolato</strong>), nulla è indicato in caso di parità.$t$, $t$<strong>Totaux et résultat</strong> : au Conseil national, <strong>calculés</strong> par le site d'après les bulletins (la source ne publie ni totaux ni résultat) ; au Conseil des États, décompte <strong>officiel</strong> de la source. Dans les deux cas, « adopté » = plus de oui que de non (<strong>calculé</strong>), rien d'indiqué en cas d'égalité.$t$),
($t$de$t$, $t$methodo-ch-groupes$t$, $t$<strong>Fraktion</strong>: die des Ratsmitglieds <em>zum Zeitpunkt der Abstimmung</em>, auf jedem Stimmzettel angegeben; die auf dem Profil angezeigte datierte Zugehörigkeit wird aus der Folge der importierten Stimmzettel <strong>abgeleitet</strong>.$t$, $t$<strong>Groupe</strong> : celui du conseiller <em>au moment du vote</em>, porté par chaque bulletin ; l'appartenance datée affichée sur la fiche est <strong>déduite</strong> de la suite des bulletins importés.$t$),
($t$it$t$, $t$methodo-ch-groupes$t$, $t$<strong>Gruppo</strong>: quello del consigliere <em>al momento del voto</em>, indicato su ogni scheda; l'appartenenza datata mostrata nella scheda personale è <strong>dedotta</strong> dalla successione delle schede importate.$t$, $t$<strong>Groupe</strong> : celui du conseiller <em>au moment du vote</em>, porté par chaque bulletin ; l'appartenance datée affichée sur la fiche est <strong>déduite</strong> de la suite des bulletins importés.$t$),
($t$de$t$, $t$methodo-ch-ensemble$t$, $t$<strong>Gesamtabstimmung</strong>: «Schlussabstimmung» und «Gesamtabstimmung» werden anhand des Abstimmungsgegenstands erkannt (<strong>berechnet</strong>); die anderen Abstimmungen (Anträge, Änderungsanträge, Motionen) erscheinen, wenn man das Kästchen ankreuzt.$t$, $t$<strong>Vote sur l'ensemble</strong> : « vote final » et « vote sur l'ensemble » sont repérés d'après l'objet du vote (<strong>calculé</strong>) ; les autres votes (propositions, amendements, motions) s'affichent en cochant la case.$t$),
($t$it$t$, $t$methodo-ch-ensemble$t$, $t$<strong>Votazione sul complesso</strong>: «votazione finale» e «votazione sul complesso» sono riconosciute in base all'oggetto del voto (<strong>calcolato</strong>); le altre votazioni (proposte, emendamenti, mozioni) compaiono spuntando la casella.$t$, $t$<strong>Vote sur l'ensemble</strong> : « vote final » et « vote sur l'ensemble » sont repérés d'après l'objet du vote (<strong>calculé</strong>) ; les autres votes (propositions, amendements, motions) s'affichent en cochant la case.$t$),
($t$de$t$, $t$methodo-ch-reunie$t$, $t$<strong>Vereinigte Bundesversammlung</strong> (Wahlen des Bundesrats, der Richter): Diese Abstimmungen mischen beide Räte und werden nicht importiert.$t$, $t$<strong>Assemblée fédérale réunie</strong> (élections du Conseil fédéral, des juges) : ces scrutins mêlent les deux conseils et ne sont pas importés.$t$),
($t$it$t$, $t$methodo-ch-reunie$t$, $t$<strong>Assemblea federale riunita</strong> (elezioni del Consiglio federale, dei giudici): queste votazioni mescolano i due consigli e non sono importate.$t$, $t$<strong>Assemblée fédérale réunie</strong> (élections du Conseil fédéral, des juges) : ces scrutins mêlent les deux conseils et ne sont pas importés.$t$),
($t$de$t$, $t$methodo-ch-conseil$t$, $t$<strong>Rat einer Abstimmung</strong>: Die Quelle gibt ihn nicht an; er ergibt sich aus dem Mandatsverzeichnis zum Datum der Abstimmung.$t$, $t$<strong>Conseil d'un vote</strong> : la source ne l'indique pas ; il se déduit de l'annuaire des mandats à la date du vote.$t$),
($t$it$t$, $t$methodo-ch-conseil$t$, $t$<strong>Consiglio di una votazione</strong>: la fonte non lo indica; si deduce dall'elenco dei mandati alla data del voto.$t$, $t$<strong>Conseil d'un vote</strong> : la source ne l'indique pas ; il se déduit de l'annuaire des mandats à la date du vote.$t$),
($t$de$t$, $t$methodo-ch-historique$t$, $t$<strong>Historische Daten</strong>: Standardmässig wird nur die laufende Legislaturperiode importiert.$t$, $t$<strong>Données historiques</strong> : seule la législature en cours est importée par défaut.$t$),
($t$it$t$, $t$methodo-ch-historique$t$, $t$<strong>Dati storici</strong>: per impostazione predefinita è importata solo la legislatura in corso.$t$, $t$<strong>Données historiques</strong> : seule la législature en cours est importée par défaut.$t$),
($t$de$t$, $t$mise-a-jour-automatique-chaque-nuit-les$t$, $t$Automatische Aktualisierung jede Nacht: Abstimmungen, die weniger als sieben Tage alt sind, werden neu gelesen. Der Code ist freie Software (GPL-3.0).$t$, $t$Mise à jour automatique chaque nuit : les votes de moins de sept jours sont relus. Le code est un logiciel libre (GPL-3.0).$t$),
($t$it$t$, $t$mise-a-jour-automatique-chaque-nuit-les$t$, $t$Aggiornamento automatico ogni notte: le votazioni di meno di sette giorni vengono rilette. Il codice è software libero (GPL-3.0).$t$, $t$Mise à jour automatique chaque nuit : les votes de moins de sept jours sont relus. Le code est un logiciel libre (GPL-3.0).$t$),
($t$de$t$, $t$les-votes-du-conseil-national-et$t$, $t$Die Abstimmungen des Nationalrats und des Ständerats, vom neuesten zum ältesten: standardmässig die Schlussabstimmungen und die Gesamtabstimmungen über eine Vorlage; kreuzen Sie das Kästchen an, um auch Abstimmungen über Anträge, Änderungsanträge und Motionen zu sehen. Im Nationalrat werden Gesamtergebnisse und Ergebnis von der Website anhand der Stimmzettel berechnet (die Quelle veröffentlicht keine); im Ständerat sind die Gesamtergebnisse die der Quelle. Klicken Sie auf einen Spaltentitel zum Sortieren; exportieren Sie die Tabelle als CSV oder JSON.$t$, $t$Les votes du Conseil national et du Conseil des États, du plus récent au plus ancien : par défaut les votes finaux et les votes sur l'ensemble d'un projet ; cochez la case pour voir aussi les votes sur des propositions, amendements et motions. Au Conseil national, les totaux et le résultat sont calculés par le site d'après les bulletins (la source n'en publie pas) ; au Conseil des États, les totaux sont ceux de la source. Cliquez sur le titre d'une colonne pour trier ; exportez le tableau en CSV ou JSON.$t$),
($t$it$t$, $t$les-votes-du-conseil-national-et$t$, $t$Le votazioni del Consiglio nazionale e del Consiglio degli Stati, dalla più recente alla più antica: per impostazione predefinita le votazioni finali e quelle sul complesso di un progetto; spuntate la casella per vedere anche le votazioni su proposte, emendamenti e mozioni. Al Consiglio nazionale i totali e il risultato sono calcolati dal sito in base alle schede (la fonte non ne pubblica); al Consiglio degli Stati i totali sono quelli della fonte. Cliccate sul titolo di una colonna per ordinare; esportate la tabella in CSV o JSON.$t$, $t$Les votes du Conseil national et du Conseil des États, du plus récent au plus ancien : par défaut les votes finaux et les votes sur l'ensemble d'un projet ; cochez la case pour voir aussi les votes sur des propositions, amendements et motions. Au Conseil national, les totaux et le résultat sont calculés par le site d'après les bulletins (la source n'en publie pas) ; au Conseil des États, les totaux sont ceux de la source. Cliquez sur le titre d'une colonne pour trier ; exportez le tableau en CSV ou JSON.$t$),
($t$de$t$, $t$pour-chaque-vote-de-l-assemblee$t$, $t$Sehen Sie bei jeder Abstimmung des Nationalrats und des Ständerats auf einen Blick, wie jedes Ratsmitglied abgestimmt hat: Ja, Nein, Enthaltung, abwesend.$t$, $t$Pour chaque vote du Conseil national et du Conseil des États, voyez d'un coup d'œil le vote de chaque élu : oui, non, abstention, absent.$t$),
($t$it$t$, $t$pour-chaque-vote-de-l-assemblee$t$, $t$Per ogni votazione del Consiglio nazionale e del Consiglio degli Stati, vedete a colpo d'occhio come ha votato ciascun consigliere: sì, no, astensione, assente.$t$, $t$Pour chaque vote du Conseil national et du Conseil des États, voyez d'un coup d'œil le vote de chaque élu : oui, non, abstention, absent.$t$),
